import React, { useState, useEffect } from 'react';
import { Link, useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import LoadingSpinner from '../common/LoadingSpinner';
import { validateLoginForm, getErrorMessage } from '../../utils/helpers';
import { SUCCESS_MESSAGES } from '../../utils/constants';

const Login = () => {
  const [formData, setFormData] = useState({
    username: '',
    password: ''
  });
  const [errors, setErrors] = useState({});
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');
  const [showResendVerification, setShowResendVerification] = useState(false);

  const { login, isAuthenticated, hasRole } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();

  // Redirect if already authenticated
  useEffect(() => {
    if (isAuthenticated()) {
      const from = location.state?.from?.pathname;
      if (from) {
        navigate(from, { replace: true });
      } else if (hasRole('ROLE_ADMIN')) {
        navigate('/admin-dashboard', { replace: true });
      } else if (hasRole('ROLE_VENDOR')) {
        navigate('/vendor-dashboard', { replace: true });
      } else {
        navigate('/', { replace: true });
      }
    }
  }, [isAuthenticated, hasRole, navigate, location]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));

    // Clear field error when user starts typing
    if (errors[name]) {
      setErrors(prev => ({
        ...prev,
        [name]: ''
      }));
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    // Validate form
    const validationErrors = validateLoginForm(formData);
    if (Object.keys(validationErrors).length > 0) {
      setErrors(validationErrors);
      return;
    }

    setLoading(true);
    setMessage('');
    setErrors({});
    setShowResendVerification(false);

    try {
      await login(formData);
      setMessage(SUCCESS_MESSAGES.LOGIN_SUCCESS);
      
      // Navigation is handled by useEffect above
    } catch (error) {
      const errorMessage = getErrorMessage(error);
      
      // Check if the error is related to email verification
      if (error.response?.status === 401 && 
          (errorMessage.toLowerCase().includes('email') || 
           errorMessage.toLowerCase().includes('verify') ||
           errorMessage.toLowerCase().includes('not verified'))) {
        setErrors({ 
          general: 'Please verify your email address before logging in. Check your email for the verification link.' 
        });
        setShowResendVerification(true);
      } else {
        setErrors({ general: errorMessage });
      }
    } finally {
      setLoading(false);
    }
  };

  const handleResendVerification = async () => {
    // You would implement this if your backend supports resending verification emails
    setMessage('If you need a new verification email, please register again or contact support.');
  };

  if (loading) {
    return <LoadingSpinner message="Signing you in..." />;
  }

  return (
    <div className="auth-container">
      <div className="auth-card">
        <div className="auth-header">
          <h2>Login to FoodTruck Hub</h2>
          <p>Access your vendor dashboard or admin panel</p>
        </div>

        {message && <div className="success-message">{message}</div>}
        {errors.general && (
          <div className="error-message">
            {errors.general}
            {showResendVerification && (
              <div style={{ marginTop: '10px' }}>
                <button 
                  type="button"
                  onClick={handleResendVerification}
                  className="btn btn-outline"
                  style={{ fontSize: '14px', padding: '5px 10px' }}
                >
                  Need new verification email?
                </button>
              </div>
            )}
          </div>
        )}

        <form onSubmit={handleSubmit} className="auth-form">
          <div className="form-group">
            <label htmlFor="username">Username</label>
            <input
              type="text"
              id="username"
              name="username"
              value={formData.username}
              onChange={handleChange}
              className={errors.username ? 'error' : ''}
              placeholder="Enter your username"
            />
            {errors.username && <span className="error-text">{errors.username}</span>}
          </div>

          <div className="form-group">
            <label htmlFor="password">Password</label>
            <input
              type="password"
              id="password"
              name="password"
              value={formData.password}
              onChange={handleChange}
              className={errors.password ? 'error' : ''}
              placeholder="Enter your password"
            />
            {errors.password && <span className="error-text">{errors.password}</span>}
          </div>

          <button type="submit" className="auth-button" disabled={loading}>
            {loading ? 'Signing In...' : 'Sign In'}
          </button>
        </form>

        <div className="auth-footer">
          <p>
            Don't have an account? 
            <Link to="/register"> Register here</Link>
          </p>
          <p>
            <small>
              Having trouble with email verification? Make sure to check your spam folder.
            </small>
          </p>
        </div>
      </div>
    </div>
  );
};

export default Login;
